select case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end as launch_cohort, count(case when category = 'Sports' then 1 end) as sports_count from products where launch_date <= '2024-01-01' and array_contains(tags, 'eco') group by case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end having count(case when category = 'Sports' then 1 end) < 1
